void init_options(Options *opts) {
    opts->width = 0;
    opts->height = 0;
    opts->output_width = 0;
    opts->output_height = 0;
    opts->chars = NULL;
    opts->chars_len = 0;
    opts->invert = 0;
    opts->border = 0;
    opts->html = 0;
    opts->colors = 0;
    opts->verbose = 0;
    opts->flipx = 0;
    opts->flipy = 0;
    opts->output_file = NULL;
    opts->html_raw = 0;
    opts->html_no_bold = 0;
    opts->red_weight = 0.2989f;
    opts->green_weight = 0.5866f;
