Image* read_jpeg(const char *filename, Options *opts) {
    FILE *file = NULL;
    jpeg_decompress_struct cinfo;
    jpeg_error_mgr jerr;
    Image *img = NULL;
    int row_stride;
    JSAMPARRAY buffer = NULL;
    int i, j, y;

    if (strcmp(filename, "-") == 0) {
        file = stdin;
    } else {
        file = fopen(filename, "rb");
        if (!file) {
            fprintf(stderr, "Error: Cannot open file %s\n", filename);
            return NULL;
        }
    }

    memset(&cinfo, 0, sizeof(cinfo));
    memset(&jerr, 0, sizeof(jerr));
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, file);
    jpeg_read_header(&cinfo, TRUE);
    jpeg_start_decompress(&cinfo);

    img = malloc(sizeof(Image));
    if (!img) {
        fprintf(stderr, "Error: Out of memory\n");
        jpeg_destroy_decompress(&cinfo);
        if (file != stdin) fclose(file);
        return NULL;
    }

    img->width = cinfo.output_width;
    img->height = cinfo.output_height;
    img->is_grayscale = (cinfo.output_components == 1);

    if (opts->verbose) {
        fprintf(stderr, "File: %s\n", filename);
        fprintf(stderr, "Source width: %d\n", cinfo.image_width);
        fprintf(stderr, "Source height: %d\n", cinfo.image_height);
        fprintf(stderr, "Source color components: %d\n", cinfo.num_components);
    }

    row_stride = cinfo.output_width * cinfo.output_components;
    buffer = (*cinfo.mem->alloc_sarray)((void*) &cinfo, JPOOL_IMAGE, row_stride, 1);

    img->data = malloc(img->width * img->height);
    if (!img->data) {
        fprintf(stderr, "Error: Out of memory\n");
        free(img);
        jpeg_destroy_decompress(&cinfo);
        if (file != stdin) fclose(file);
        return NULL;
    }
    memset(img->data, 0, img->width * img->height);

    y = 0;
    while (cinfo.output_scanline < cinfo.output_height) {
        if (opts->verbose && y % 10 == 0) {
            int total = cinfo.output_height;
            int percent = (y * 50) / total;
            fprintf(stderr, "Decompressing image [");
            for (i = 0; i < percent; i++) fprintf(stderr, "#");
            for (i = percent; i < 50; i++) fprintf(stderr, ".");
            fprintf(stderr, "]\r");
            fflush(stderr);
        }

        jpeg_read_scanlines(&cinfo, buffer, 1);

        for (i = 0; i < img->width; i++) {
            unsigned char val = 0;
            if (cinfo.output_components == 1) {
                val = buffer[0][i];
            } else if (cinfo.output_components == 3) {
                float r = buffer[0][i*3];
                float g = buffer[0][i*3+1];
                float b = buffer[0][i*3+2];
                val = (unsigned char)(opts->red_weight * r + opts->green_weight * g + opts->blue_weight * b);
            }
            img->data[y * img->width + i] = val;
        }
        y++;
    }

    if (opts->verbose) {
        fprintf(stderr, "Decompressing image [##################################################]\n");
    }

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);

    if (file != stdin) {
        fclose(file);
    }

    return img;
