void calculate_output_size(Image *img, Options *opts) {
    int term_width = 80;
    int term_height = 24;

    // Try to get terminal size
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) != -1) {
        term_width = ws.ws_col;
        term_height = ws.ws_row;
    }

    if (opts->term_zoom) {
        opts->output_width = term_width;
        opts->output_height = term_height;
    } else if (opts->term_height) {
        opts->output_height = term_height;
        opts->output_width = (int)((float)img->width / img->height * opts->output_height);
    } else if (opts->term_width) {
        opts->output_width = term_width;
        opts->output_height = (int)((float)img->height / img->width * opts->output_width);
    } else if (opts->term_fit) {
        float aspect = (float)img->width / img->height;
        // Account for character aspect ratio (roughly 1:2)
        float fit_width = (float)term_width;
        float fit_height = term_height * 2.0f;

        if (fit_width / aspect < fit_height) {
            opts->output_width = term_width;
            opts->output_height = (int)(term_width / aspect / 2.0f);
        } else {
            opts->output_height = term_height;
            opts->output_width = (int)(term_height * aspect * 2.0f);
        }
    } else if (opts->width && opts->height) {
        opts->output_width = opts->width;
        opts->output_height = opts->height;
    } else if (opts->width) {
        opts->output_width = opts->width;
        opts->output_height = (int)((float)img->height / img->width * opts->output_width);
    } else if (opts->height) {
        opts->output_height = opts->height;
        opts->output_width = (int)((float)img->width / img->height * opts->output_height);
    } else {
        opts->output_width = term_width;
        opts->output_height = term_height;
    }

    if (opts->output_width < 1) opts->output_width = 1;
    if (opts->output_height < 1) opts->output_height = 1;
}

unsigned char get_pixel(Image *img, int x, int y) {
    if (x < 0 || x >= img->width || y < 0 || y >= img->height) {
        return 0;
    }
    return img->data[y * img->width + x];
}

char* convert_image_to_ascii(Image *img, Options *opts) {
    char *output = malloc((opts->output_width + 1) * opts->output_height + 1);
    int pos = 0;
    int i, j;

    for (j = 0; j < opts->output_height; j++) {
        for (i = 0; i < opts->output_width; i++) {
            float fx = (float)i / opts->output_width * img->width;
            float fy = (float)j / opts->output_height * img->height;

            int x = (int)fx;
            int y = (int)fy;

            unsigned char pixel = get_pixel(img, x, y);

            int char_idx = (pixel * (opts->chars_len - 1)) / 255;
            if (opts->invert) {
                char_idx = opts->chars_len - 1 - char_idx;
            }

            output[pos++] = opts->chars[char_idx];
        }
        output[pos++] = '\n';
    }
    output[pos] = '\0';

    return output;
}

void apply_flipx(char *output, int width, int height) {
    int row, col;
    char temp;
    int line_len = width + 1;

    for (row = 0; row < height; row++) {
        for (col = 0; col < width / 2; col++) {
            int pos1 = row * line_len + col;
            int pos2 = row * line_len + (width - 1 - col);
            temp = output[pos1];
            output[pos1] = output[pos2];
            output[pos2] = temp;
        }
    }
}

void apply_flipy(char *output, int width, int height) {
    int row;
    char *temp_line = malloc(width + 1);
    int line_len = width + 1;

    for (row = 0; row < height / 2; row++) {
        int pos1 = row * line_len;
        int pos2 = (height - 1 - row) * line_len;

        memcpy(temp_line, output + pos1, width);
        memcpy(output + pos1, output + pos2, width);
        memcpy(output + pos2, temp_line, width);
    }

    free(temp_line);
}

void print_ascii(char *output, Options *opts) {
    FILE *out_file = stdout;
    int i = 0;
    int line = 0;
    int char_count = 0;

    if (opts->output_file && strcmp(opts->output_file, "-") != 0) {
        out_file = fopen(opts->output_file, "w");
        if (!out_file) {
            fprintf(stderr, "Error: Cannot open output file %s\n", opts->output_file);
            return;
        }
    }

    if (opts->clear) {
        fprintf(out_file, "\033[2J\033[H");
    }

    if (opts->border) {
        fprintf(out_file, "+");
        for (i = 0; i < opts->output_width; i++) fprintf(out_file, "-");
        fprintf(out_file, "+\n");
    }

    i = 0;
    line = 0;
    char_count = 0;
    while (output[i]) {
        if (output[i] == '\n') {
            if (opts->border) fprintf(out_file, "|");
            fprintf(out_file, "\n");
            line++;
            char_count = 0;
            i++;
        } else {
            if (opts->border && char_count == 0) {
                fprintf(out_file, "|");
            }
            fputc(output[i], out_file);
            char_count++;
            i++;
        }
    }

    if (opts->border) {
        fprintf(out_file, "+");
        for (i = 0; i < opts->output_width; i++) fprintf(out_file, "-");
        fprintf(out_file, "+\n");
    }

    if (out_file != stdout) {
        fclose(out_file);
    }
}

void print_html(char *output, Options *opts) {
    FILE *out_file = stdout;

    if (opts->output_file && strcmp(opts->output_file, "-") != 0) {
        out_file = fopen(opts->output_file, "w");
