    printf("      --term-width  Use terminal display width.\n");
    printf("  -z, --term-zoom   Use terminal display dimension for output.\n");
    printf("      --grayscale   Convert image to grayscale when using --html or --colors\n");
    printf("      --green=N.N   Set RGB to grayscale conversion weight, default is 0.5866\n");
    printf("      --height=N    Set output height, calculate width from aspect ratio.\n");
    printf("  -h, --help        Print program help.\n");
