    printf("      --html-fontsize=N   Set fontsize to N pt, default is 4.\n");
    printf("      --html-no-bold      Do not use bold characters with HTML output\n");
    printf("      --html-raw    Output raw HTML codes, i.e. without the <head> section etc.\n");
    printf("      --html-title=...  Set HTML output title\n");
    printf("  -i, --invert      Invert output image.  Use if your display has a dark\n");
    printf("                    background.\n");
    printf("      --background=dark   These are just mnemonics whether to use --invert\n");
    printf("      --background=light  or not.  If your console has light characters on\n");
    printf("                    a dark background, use --background=dark.\n");
    printf("      --output=...  Write output to file.\n");
