    opts->html_raw = 0;
    opts->html_no_bold = 0;
    opts->red_weight = 0.2989f;
    opts->green_weight = 0.5866f;
    opts->blue_weight = 0.1145f;
    opts->html_fill = 0;
    opts->clear = 0;
    opts->term_fit = 1;
    opts->term_width = 0;
    opts->term_height = 0;
    opts->term_zoom = 0;
    opts->grayscale = 0;
    opts->html_fontsize = 4;
    opts->html_title = NULL;
    opts->background = NULL;
}

Image* read_jpeg(const char *filename, Options *opts) {
    FILE *file = NULL;
    jpeg_decompress_struct cinfo;
    jpeg_error_mgr jerr;
    Image *img = NULL;
    int row_stride;
    JSAMPARRAY buffer = NULL;
    int i, y;

    if (strcmp(filename, "-") == 0) {
        file = stdin;
    } else {
        file = fopen(filename, "rb");
        if (!file) {
            fprintf(stderr, "Error: Cannot open file %s\n", filename);
            return NULL;
        }
    }

    memset(&cinfo, 0, sizeof(cinfo));
    memset(&jerr, 0, sizeof(jerr));
    cinfo.err = jpeg_std_error_ptr(&jerr);
    jpeg_create_decompress_ptr(&cinfo);
    jpeg_stdio_src_ptr(&cinfo, file);
    jpeg_read_header_ptr(&cinfo, TRUE);
    jpeg_start_decompress_ptr(&cinfo);

    img = malloc(sizeof(Image));
    if (!img) {
        fprintf(stderr, "Error: Out of memory\n");
        jpeg_destroy_decompress_ptr(&cinfo);
        if (file != stdin) fclose(file);
        return NULL;
    }

    img->width = cinfo.output_width;
    img->height = cinfo.output_height;
    img->is_grayscale = (cinfo.output_components == 1);

    if (opts->verbose) {
        fprintf(stderr, "File: %s\n", filename);
        fprintf(stderr, "Source width: %d\n", cinfo.image_width);
        fprintf(stderr, "Source height: %d\n", cinfo.image_height);
        fprintf(stderr, "Source color components: %d\n", cinfo.num_components);
    }

    row_stride = cinfo.output_width * cinfo.output_components;
    buffer = (*cinfo.mem->alloc_sarray)((void*) &cinfo, 0, row_stride, 1);

    img->data = malloc(img->width * img->height);
    if (!img->data) {
        fprintf(stderr, "Error: Out of memory\n");
        free(img);
        jpeg_destroy_decompress_ptr(&cinfo);
        if (file != stdin) fclose(file);
        return NULL;
    }
    memset(img->data, 0, img->width * img->height);

    y = 0;
    while (cinfo.output_scanline < cinfo.output_height) {
        if (opts->verbose && y % 10 == 0) {
            int total = cinfo.output_height;
            int percent = (y * 50) / total;
            fprintf(stderr, "Decompressing image [");
            for (i = 0; i < percent; i++) fprintf(stderr, "#");
            for (i = percent; i < 50; i++) fprintf(stderr, ".");
            fprintf(stderr, "]\r");
            fflush(stderr);
        }

        jpeg_read_scanlines_ptr(&cinfo, buffer, 1);

        for (i = 0; i < img->width; i++) {
            unsigned char val = 0;
            if (cinfo.output_components == 1) {
                val = buffer[0][i];
            } else if (cinfo.output_components == 3) {
                float r = buffer[0][i*3];
                float g = buffer[0][i*3+1];
                float b = buffer[0][i*3+2];
                val = (unsigned char)(opts->red_weight * r + opts->green_weight * g + opts->blue_weight * b);
            }
            img->data[y * img->width + i] = val;
        }
        y++;
    }

    if (opts->verbose) {
        fprintf(stderr, "Decompressing image [##################################################]\n");
    }

    jpeg_finish_decompress_ptr(&cinfo);
    jpeg_destroy_decompress_ptr(&cinfo);

    if (file != stdin) {
        fclose(file);
    }

    return img;
}

void free_image(Image *img) {
    if (img) {
        if (img->data) free(img->data);
        free(img);
    }
}

void calculate_output_size(Image *img, Options *opts) {
    int term_width = 80;
    int term_height = 24;

    // Try to get terminal size
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) != -1) {
        term_width = ws.ws_col;
        term_height = ws.ws_row;
    }

    if (opts->term_zoom) {
        opts->output_width = term_width;
        opts->output_height = term_height;
    } else if (opts->term_height) {
        opts->output_height = term_height;
        opts->output_width = (int)((float)img->width / img->height * opts->output_height);
    } else if (opts->term_width) {
        opts->output_width = term_width;
        opts->output_height = (int)((float)img->height / img->width * opts->output_width);
    } else if (opts->term_fit) {
        float aspect = (float)img->width / img->height;
        // Account for character aspect ratio (roughly 1:2)
        float fit_width = (float)term_width;
        float fit_height = term_height * 2.0f;

        if (fit_width / aspect < fit_height) {
            opts->output_width = term_width;
            opts->output_height = (int)(term_width / aspect / 2.0f);
        } else {
            opts->output_height = term_height;
            opts->output_width = (int)(term_height * aspect * 2.0f);
        }
    } else if (opts->width && opts->height) {
        opts->output_width = opts->width;
        opts->output_height = opts->height;
    } else if (opts->width) {
        opts->output_width = opts->width;
        opts->output_height = (int)((float)img->height / img->width * opts->output_width);
    } else if (opts->height) {
        opts->output_height = opts->height;
        opts->output_width = (int)((float)img->width / img->height * opts->output_height);
    } else {
        opts->output_width = term_width;
        opts->output_height = term_height;
    }

    if (opts->output_width < 1) opts->output_width = 1;
    if (opts->output_height < 1) opts->output_height = 1;
}

unsigned char get_pixel(Image *img, int x, int y) {
    if (x < 0 || x >= img->width || y < 0 || y >= img->height) {
        return 0;
    }
    return img->data[y * img->width + x];
}

char* convert_image_to_ascii(Image *img, Options *opts) {
    char *output = malloc((opts->output_width + 1) * opts->output_height + 1);
    int pos = 0;
    int i, j;

    for (j = 0; j < opts->output_height; j++) {
        for (i = 0; i < opts->output_width; i++) {
            float fx = (float)i / opts->output_width * img->width;
            float fy = (float)j / opts->output_height * img->height;

            int x = (int)fx;
            int y = (int)fy;

            unsigned char pixel = get_pixel(img, x, y);

            int char_idx = (pixel * (opts->chars_len - 1)) / 255;
            if (opts->invert) {
                char_idx = opts->chars_len - 1 - char_idx;
            }

            output[pos++] = opts->chars[char_idx];
        }
        output[pos++] = '\n';
    }
    output[pos] = '\0';

    return output;
}

void apply_flipx(char *output, int width, int height) {
    int row, col;
    char temp;
    int line_len = width + 1;

    for (row = 0; row < height; row++) {
        for (col = 0; col < width / 2; col++) {
            int pos1 = row * line_len + col;
            int pos2 = row * line_len + (width - 1 - col);
            temp = output[pos1];
            output[pos1] = output[pos2];
            output[pos2] = temp;
        }
    }
}

void apply_flipy(char *output, int width, int height) {
    int row;
    char *temp_line = malloc(width + 1);
    int line_len = width + 1;

    for (row = 0; row < height / 2; row++) {
        int pos1 = row * line_len;
        int pos2 = (height - 1 - row) * line_len;

        memcpy(temp_line, output + pos1, width);
        memcpy(output + pos1, output + pos2, width);
        memcpy(output + pos2, temp_line, width);
    }

    free(temp_line);
}

void print_ascii(char *output, Options *opts) {
    FILE *out_file = stdout;
    int i = 0;
    int line = 0;
    int char_count = 0;

    if (opts->output_file && strcmp(opts->output_file, "-") != 0) {
        out_file = fopen(opts->output_file, "w");
        if (!out_file) {
            fprintf(stderr, "Error: Cannot open output file %s\n", opts->output_file);
            return;
        }
    }

    if (opts->clear) {
        fprintf(out_file, "\033[2J\033[H");
    }

    if (opts->border) {
        fprintf(out_file, "+");
        for (i = 0; i < opts->output_width; i++) fprintf(out_file, "-");
        fprintf(out_file, "+\n");
    }

    i = 0;
    line = 0;
    char_count = 0;
    while (output[i]) {
        if (output[i] == '\n') {
            if (opts->border) fprintf(out_file, "|");
            fprintf(out_file, "\n");
            line++;
            char_count = 0;
            i++;
        } else {
            if (opts->border && char_count == 0) {
                fprintf(out_file, "|");
            }
            fputc(output[i], out_file);
            char_count++;
            i++;
        }
    }

    if (opts->border) {
        fprintf(out_file, "+");
        for (i = 0; i < opts->output_width; i++) fprintf(out_file, "-");
        fprintf(out_file, "+\n");
    }

    if (out_file != stdout) {
        fclose(out_file);
    }
}

void print_html(char *output, Options *opts) {
    FILE *out_file = stdout;

    if (opts->output_file && strcmp(opts->output_file, "-") != 0) {
        out_file = fopen(opts->output_file, "w");
        if (!out_file) {
            fprintf(stderr, "Error: Cannot open output file %s\n", opts->output_file);
            return;
        }
    }

    if (!opts->html_raw) {
        fprintf(out_file, "<?xml version='1.0' encoding='ISO-8859-1'?>\n");
        fprintf(out_file, "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n");
        fprintf(out_file, "<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n");
        fprintf(out_file, "<head>\n");
        fprintf(out_file, "<title>%s</title>\n", opts->html_title ? opts->html_title : "jp2a converted image");
        fprintf(out_file, "<style type='text/css'>\n");
        fprintf(out_file, "body {\n");
        fprintf(out_file, "background-color: black;\n");
        fprintf(out_file, "}\n");
        fprintf(out_file, ".ascii {\n");
        fprintf(out_file, "   font-family: Courier;\n");
        fprintf(out_file, "   color: white;\n");
        fprintf(out_file, "   font-size:%dpt;\n", opts->html_fontsize * 2);
        if (!opts->html_no_bold) {
            fprintf(out_file, "   font-weight: bold;\n");
        }
        fprintf(out_file, "}\n");
        fprintf(out_file, "</style>\n");
        fprintf(out_file, "</head>\n");
        fprintf(out_file, "<body>\n");
    }

    fprintf(out_file, "<div class='ascii'><pre>\n");
    fprintf(out_file, "%s", output);
    fprintf(out_file, "</pre>\n");
    fprintf(out_file, "</div>\n");

    if (!opts->html_raw) {
        fprintf(out_file, "</body>\n");
        fprintf(out_file, "</html>\n");
    }

    if (out_file != stdout) {
        fclose(out_file);
    }
}

int main(int argc, char *argv[]) {
    Options opts;
    int i, c;
    char *chars = NULL;
    int file_count = 0;
    char **files = NULL;

    load_jpeg_lib();

    init_options(&opts);
    opts.chars = DEFAULT_CHARS;
    opts.chars_len = strlen(DEFAULT_CHARS);

    struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"version", no_argument, 0, 'V'},
        {"width", required_argument, 0, 'w'},
        {"height", required_argument, 0, 'H'},
        {"size", required_argument, 0, 's'},
        {"chars", required_argument, 0, 'c'},
        {"invert", no_argument, 0, 'i'},
        {"border", no_argument, 0, 'b'},
        {"html", no_argument, 0, 'x'},
        {"colors", no_argument, 0, 'C'},
        {"verbose", no_argument, 0, 'v'},
        {"flipx", no_argument, 0, 'X'},
        {"flipy", no_argument, 0, 'Y'},
        {"output", required_argument, 0, 'o'},
        {"html-raw", no_argument, 0, 'r'},
        {"html-no-bold", no_argument, 0, 'n'},
        {"red", required_argument, 0, 'R'},
        {"green", required_argument, 0, 'G'},
        {"blue", required_argument, 0, 'B'},
        {"fill", no_argument, 0, 'f'},
        {"html-fill", no_argument, 0, 'f'},
        {"clear", no_argument, 0, 'l'},
        {"term-fit", no_argument, 0, 'F'},
        {"term-width", no_argument, 0, 'W'},
        {"term-height", no_argument, 0, 'T'},
        {"term-zoom", no_argument, 0, 'z'},
        {"grayscale", no_argument, 0, 'g'},
        {"html-fontsize", required_argument, 0, 'p'},
        {"html-title", required_argument, 0, 't'},
        {"background", required_argument, 0, 'k'},
        {"debug", no_argument, 0, 'd'},
        {0, 0, 0, 0}
    };

    while ((c = getopt_long(argc, argv, "hVw:H:s:c:ibxCvXYo:rnR:G:B:flFWTzgp:t:k:d", long_options, NULL)) != -1) {
        switch (c) {
            case 'h':
                print_help();
                return 0;
            case 'V':
                print_version();
                return 0;
            case 'w':
                opts.width = atoi(optarg);
                opts.term_fit = 0;
                break;
            case 'H':
                opts.height = atoi(optarg);
                opts.term_fit = 0;
                break;
            case 's': {
                char *x = strchr(optarg, 'x');
                if (x) {
                    opts.width = atoi(optarg);
                    opts.height = atoi(x + 1);
                    opts.term_fit = 0;
                }
                break;
            }
            case 'c':
                chars = optarg;
                break;
            case 'i':
                opts.invert = 1;
                break;
            case 'b':
                opts.border = 1;
                break;
            case 'x':
                opts.html = 1;
                break;
            case 'C':
                opts.colors = 1;
                break;
            case 'v':
                opts.verbose = 1;
                break;
            case 'X':
                opts.flipx = 1;
                break;
            case 'Y':
                opts.flipy = 1;
                break;
            case 'o':
                opts.output_file = optarg;
                break;
            case 'r':
                opts.html_raw = 1;
                break;
            case 'n':
                opts.html_no_bold = 1;
                break;
            case 'R':
                opts.red_weight = atof(optarg);
                break;
            case 'G':
                opts.green_weight = atof(optarg);
                break;
            case 'B':
                opts.blue_weight = atof(optarg);
                break;
            case 'f':
                opts.html_fill = 1;
                break;
            case 'l':
                opts.clear = 1;
                break;
            case 'F':
                opts.term_fit = 1;
                break;
            case 'W':
                opts.term_width = 1;
                opts.term_fit = 0;
                break;
            case 'T':
                opts.term_height = 1;
                opts.term_fit = 0;
                break;
            case 'z':
                opts.term_zoom = 1;
                opts.term_fit = 0;
                break;
            case 'g':
                opts.grayscale = 1;
                break;
            case 'p':
                opts.html_fontsize = atoi(optarg);
                break;
            case 't':
                opts.html_title = optarg;
                break;
            case 'k':
                opts.background = optarg;
                if (strcmp(optarg, "dark") == 0) {
                    opts.invert = 1;
                } else if (strcmp(optarg, "light") == 0) {
                    opts.invert = 0;
                }
                break;
            case 'd':
                opts.verbose = 1;
                break;
        }
    }

    if (chars) {
        opts.chars = chars;
        opts.chars_len = strlen(chars);
    }

    // Collect remaining arguments as files
    for (i = optind; i < argc; i++) {
        file_count++;
        files = realloc(files, sizeof(char*) * file_count);
        files[file_count - 1] = argv[i];
    }

    if (file_count == 0) {
        printf("No files specified.\n");
        printf("\n");
        print_version();
        return 0;
    }

    for (i = 0; i < file_count; i++) {
        Image *img = read_jpeg(files[i], &opts);
        if (!img) {
            continue;
        }

        calculate_output_size(img, &opts);

        if (opts.verbose) {
            fprintf(stderr, "Output width: %d\n", opts.output_width);
            fprintf(stderr, "Output height: %d\n", opts.output_height);
            fprintf(stderr, "Output palette (%d chars): '%s'\n", opts.chars_len, opts.chars);
        }

        char *ascii = convert_image_to_ascii(img, &opts);

        if (opts.flipx) {
            apply_flipx(ascii, opts.output_width, opts.output_height);
        }

        if (opts.flipy) {
            apply_flipy(ascii, opts.output_width, opts.output_height);
        }

        if (opts.html) {
            print_html(ascii, &opts);
        } else {
            print_ascii(ascii, &opts);
        }

        free(ascii);
        free_image(img);
    }

    free(files);

    return 0;
}
