// Simple PPM decoder (djpeg will convert JPEG to PPM)
Image* load_ppm(FILE *f) {
    Image *img = malloc(sizeof(Image));
    char magic[3];
    int width, height, max_val;

    // Read magic
    fscanf(f, "%2s", magic);
    if (strcmp(magic, "P6") != 0 && strcmp(magic, "P5") != 0) {
        free(img);
        return NULL;
    }

    // Skip whitespace and comments
    int c;
    while ((c = fgetc(f)) != EOF && (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '#')) {
