package main

import (
	"bufio"
	"flag"
	"fmt"
	"image"
	"image/jpeg"
	"log"
	"os"
	"strings"
)

const (
	VERSION       = "1.0.8"
	DEFAULT_CHARS = "   ...',;:clodxkO0KXNWM"
)

type Options struct {
	width        int
	height       int
	outputWidth  int
	outputHeight int
	chars        string
	invert       bool
	border       bool
