func printVersion() {
	fmt.Printf("jp2a %s\n", VERSION)
	fmt.Printf("Copyright 2006-2016 Christian Stigen Larsen\n")
	fmt.Printf("Distributed under the GNU General Public License (GPL) v2.\n")
}

func printHelp() {
	printVersion()
	fmt.Println()
	fmt.Println("Usage: jp2a [ options ] [ file(s) | URL(s) ]")
	fmt.Println()
	fmt.Println("Convert files or URLs from JPEG format to ASCII.")
	fmt.Println()
	fmt.Println("OPTIONS")
