	fmt.Println("  -y, --flipy       Flip vertically.")
	fmt.Println("  -v, --verbose     Verbose output.")
	fmt.Println("  --output=FILE     Write to file.")
}

func readJPEG(filename string, opts *Options) ([]uint8, int, int, error) {
	var file *os.File
	var err error

	if filename == "-" {
		file = os.Stdin
	} else {
		file, err = os.Open(filename)
		if err != nil {
			return nil, 0, 0, err
		}
		defer file.Close()
	}

	img, err := jpeg.Decode(file)
	if err != nil {
		return nil, 0, 0, err
	}

	bounds := img.Bounds()
	width := bounds.Max.X - bounds.Min.X
	height := bounds.Max.Y - bounds.Min.Y

	if opts.verbose {
		fmt.Fprintf(os.Stderr, "File: %s\n", filename)
		fmt.Fprintf(os.Stderr, "Source width: %d\n", width)
		fmt.Fprintf(os.Stderr, "Source height: %d\n", height)
		fmt.Fprintf(os.Stderr, "Source color components: 3\n")
	}

	// Convert to grayscale
	grayscale := make([]uint8, width*height)
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			r, g, b, _ := img.At(x+bounds.Min.X, y+bounds.Min.Y).RGBA()
			// Convert from 16-bit to 8-bit
			r >>= 8
			g >>= 8
			b >>= 8
			// Luminance formula
			lum := uint8(0.2989*float64(r) + 0.5866*float64(g) + 0.1145*float64(b))
			grayscale[y*width+x] = lum
		}
	}

	return grayscale, width, height, nil
}

func pixelToASCII(pixel uint8, chars string, invert bool) rune {
	charIdx := int((float64(pixel) / 255.0) * float64(len(chars)-1))
	if invert {
		charIdx = len(chars) - 1 - charIdx
	}
	return rune(chars[charIdx])
}

func resizeImage(pixels []uint8, oldW, oldH, newW, newH int) []uint8 {
	resized := make([]uint8, newW*newH)
	for y := 0; y < newH; y++ {
		for x := 0; x < newW; x++ {
			srcX := int((float64(x) / float64(newW)) * float64(oldW))
			srcY := int((float64(y) / float64(newH)) * float64(oldH))
			srcIdx := srcY*oldW + srcX
			if srcIdx >= len(pixels) {
				srcIdx = len(pixels) - 1
			}
			resized[y*newW+x] = pixels[srcIdx]
		}
	}
	return resized
}

func convertToASCII(pixels []uint8, width, height int, opts *Options) []string {
	result := make([]string, height)
	for y := 0; y < height; y++ {
		line := ""
		for x := 0; x < width; x++ {
			idx := y*width + x
			if idx < len(pixels) {
				line += string(pixelToASCII(pixels[idx], opts.chars, opts.invert))
			} else {
				line += string(opts.chars[0])
			}
		}
		result[y] = line
	}
	return result
}

func flipX(lines []string) []string {
	for i := range lines {
		runes := []rune(lines[i])
		for j, k := 0, len(runes)-1; j < k; j, k = j+1, k-1 {
			runes[j], runes[k] = runes[k], runes[j]
		}
		lines[i] = string(runes)
	}
	return lines
}

func flipY(lines []string) []string {
	for i, j := 0, len(lines)-1; i < j; i, j = i+1, j-1 {
		lines[i], lines[j] = lines[j], lines[i]
	}
	return lines
}

func output(lines []string, opts *Options) error {
	var out *os.File
	var err error

	if opts.outputFile != "" && opts.outputFile != "-" {
		out, err = os.Create(opts.outputFile)
		if err != nil {
			return err
		}
		defer out.Close()
	} else {
		out = os.Stdout
	}

	writer := bufio.NewWriter(out)

	if opts.html {
		fmt.Fprintln(writer, "<?xml version='1.0' encoding='ISO-8859-1'?>")
		fmt.Fprintln(writer, "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>")
		fmt.Fprintln(writer, "<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>")
		fmt.Fprintln(writer, "<head>")
		title := opts.htmlTitle
		if title == "" {
			title = "jp2a converted image"
		}
		fmt.Fprintf(writer, "<title>%s</title>\n", title)
		fmt.Fprintln(writer, "<style type='text/css'>")
		fmt.Fprintln(writer, "body {")
		fmt.Fprintln(writer, "background-color: black;")
		fmt.Fprintln(writer, "}")
		fmt.Fprintln(writer, ".ascii {")
		fmt.Fprintln(writer, "   font-family: Courier;")
		fmt.Fprintln(writer, "   color: white;")
		fmt.Fprintf(writer, "   font-size:%dpt;\n", opts.htmlFontsize*2)
		if !opts.htmlNoBold {
			fmt.Fprintln(writer, "   font-weight: bold;")
		}
		fmt.Fprintln(writer, "}")
		fmt.Fprintln(writer, "</style>")
		fmt.Fprintln(writer, "</head>")
		fmt.Fprintln(writer, "<body>")
		fmt.Fprintln(writer, "<div class='ascii'><pre>")
	}

	if opts.border {
		fmt.Fprint(writer, "+")
		for i := 0; i < opts.outputWidth; i++ {
			fmt.Fprint(writer, "-")
		}
		fmt.Fprintln(writer, "+")
	}

	for _, line := range lines {
		if opts.border {
			fmt.Fprint(writer, "|")
		}
		fmt.Fprintln(writer, line)
		if opts.border {
			fmt.Fprint(writer, "|")
		}
	}

	if opts.border {
		fmt.Fprint(writer, "+")
		for i := 0; i < opts.outputWidth; i++ {
			fmt.Fprint(writer, "-")
		}
		fmt.Fprintln(writer, "+")
	}

	if opts.html {
		fmt.Fprintln(writer, "</pre>")
		fmt.Fprintln(writer, "</div>")
		fmt.Fprintln(writer, "</body>")
		fmt.Fprintln(writer, "</html>")
	}

	return writer.Flush()
}

func main() {
	opts := &Options{
		outputWidth:  80,
		outputHeight: 24,
		chars:        DEFAULT_CHARS,
		htmlFontsize: 4,
	}

	fs := flag.NewFlagSet("jp2a", flag.ContinueOnError)
	fs.IntVar(&opts.width, "w", 0, "Output width")
	fs.IntVar(&opts.height, "H", 0, "Output height")
	fs.StringVar(&opts.chars, "c", DEFAULT_CHARS, "Character palette")
	fs.BoolVar(&opts.invert, "i", false, "Invert")
	fs.BoolVar(&opts.border, "b", false, "Border")
	fs.BoolVar(&opts.html, "html", false, "HTML output")
	fs.BoolVar(&opts.flipx, "x", false, "Flip X")
	fs.BoolVar(&opts.flipy, "y", false, "Flip Y")
	fs.BoolVar(&opts.verbose, "v", false, "Verbose")
	fs.StringVar(&opts.outputFile, "o", "", "Output file")

	// Register long options
	var showHelp, showVersion bool
	var sizeStr string
	fs.BoolVar(&showHelp, "help", false, "Show help")
	fs.BoolVar(&showVersion, "version", false, "Show version")
	fs.StringVar(&sizeStr, "size", "", "Size WxH")
	fs.StringVar(&sizeStr, "s", "", "Size WxH")

	err := fs.Parse(os.Args[1:])
	if err != nil {
		printHelp()
		os.Exit(1)
	}

	if showVersion || (len(os.Args) > 1 && os.Args[1] == "-V") {
		printVersion()
		os.Exit(0)
	}

	if showHelp || (len(os.Args) > 1 && os.Args[1] == "-h") {
		printHelp()
		os.Exit(0)
	}

	// Parse size if provided
	if sizeStr != "" {
		parts := strings.Split(sizeStr, "x")
		if len(parts) == 2 {
			fmt.Sscanf(parts[0], "%d", &opts.outputWidth)
			fmt.Sscanf(parts[1], "%d", &opts.outputHeight)
		}
	}

	// Apply width/height overrides
	if opts.width > 0 {
		opts.outputWidth = opts.width
	}
	if opts.height > 0 {
		opts.outputHeight = opts.height
	}

	files := fs.Args()

	if len(files) == 0 {
		fmt.Println("No files specified.")
		fmt.Println()
		printVersion()
		os.Exit(0)
	}

	for _, filename := range files {
		pixels, width, height, err := readJPEG(filename, opts)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			continue
		}

		if opts.verbose {
			fmt.Fprintf(os.Stderr, "Output width: %d\n", opts.outputWidth)
			fmt.Fprintf(os.Stderr, "Output height: %d\n", opts.outputHeight)
			fmt.Fprintf(os.Stderr, "Output palette (%d chars): '%s'\n", len(opts.chars), opts.chars)
		}

		// Resize
		resized := resizeImage(pixels, width, height, opts.outputWidth, opts.outputHeight)

		// Convert to ASCII
		lines := convertToASCII(resized, opts.outputWidth, opts.outputHeight, opts)

		// Apply transformations
		if opts.flipx {
			lines = flipX(lines)
		}
		if opts.flipy {
			lines = flipY(lines)
		}

		// Output
		err = output(lines, opts)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		}
	}
}
