		lines := convertToASCII(resized, opts.outputWidth, opts.outputHeight, opts)

		// Apply transformations
		if opts.flipx {
			lines = flipX(lines)
		}
		if opts.flipy {
			lines = flipY(lines)
		}

		// Output
		err = output(lines, opts)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		}
	}
}
